import axios from "axios";
import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";

export default function Inventory() {
  const [inventory, setInventory] = useState([]);
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();

  // GET Inventory
  const fetchInventory = async () => {
    try {
      setLoading(true);

      const token = localStorage.getItem("token");

      const response = await axios.get(
        "http://localhost:5000/api/v1/inventory",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log("Inventory:", response.data);

      setInventory(response.data);

    } catch (error) {
      console.log(
        error.response?.data || error.message
      );
    } finally {
      setLoading(false);
    }
  };

  // DELETE Inventory
  const deleteInventory = async (id) => {
    const confirmDelete = window.confirm(
      "Are you sure you want to delete this inventory?"
    );

    if (!confirmDelete) return;

    try {
      const token = localStorage.getItem("token");

      await axios.delete(
        `http://localhost:5000/api/v1/inventory/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      alert("Inventory Deleted Successfully");

      fetchInventory();

    } catch (error) {
      console.log(
        error.response?.data || error.message
      );

      alert("Delete Failed");
    }
  };

  useEffect(() => {
    fetchInventory();
  }, []);

  return (
    <div className="container-fluid bg-light min-vh-100 py-4">

      <div className="container">

        {/* Header */}
        <div className="card border-0 shadow-sm mb-4">

          <div className="card-body">

            <div className="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3">

              <div>

                <h2 className="fw-bold mb-1">
                  📦 Inventory
                </h2>

                <p className="text-muted mb-0">
                  Manage your product stock
                </p>

              </div>

              <button
                className="btn btn-primary px-4"
                onClick={() =>
                  navigate("/add-inventory")
                }
              >
                + Add Inventory
              </button>

            </div>

          </div>

        </div>


        {/* Statistics */}
        <div className="row g-4 mb-4">

          {/* Total Items */}
          <div className="col-md-4">

            <div className="card border-0 shadow-sm">

              <div className="card-body">

                <div className="d-flex justify-content-between align-items-center">

                  <div>

                    <p className="text-muted mb-1">
                      Total Inventory Items
                    </p>

                    <h3 className="fw-bold mb-0">
                      {inventory.length}
                    </h3>

                  </div>

                  <div
                    className="bg-primary text-white rounded-circle d-flex align-items-center justify-content-center"
                    style={{
                      width: "55px",
                      height: "55px",
                      fontSize: "24px",
                    }}
                  >
                    📦
                  </div>

                </div>

              </div>

            </div>

          </div>


          {/* Total Stock */}
          <div className="col-md-4">

            <div className="card border-0 shadow-sm">

              <div className="card-body">

                <div className="d-flex justify-content-between align-items-center">

                  <div>

                    <p className="text-muted mb-1">
                      Total Stock
                    </p>

                    <h3 className="fw-bold mb-0">
                      {inventory.reduce(
                        (total, item) =>
                          total +
                          Number(item.stock || 0),
                        0
                      )}
                    </h3>

                  </div>

                  <div
                    className="bg-success text-white rounded-circle d-flex align-items-center justify-content-center"
                    style={{
                      width: "55px",
                      height: "55px",
                      fontSize: "24px",
                    }}
                  >
                    📊
                  </div>

                </div>

              </div>

            </div>

          </div>


          {/* Low Stock */}
          <div className="col-md-4">

            <div className="card border-0 shadow-sm">

              <div className="card-body">

                <div className="d-flex justify-content-between align-items-center">

                  <div>

                    <p className="text-muted mb-1">
                      Low Stock
                    </p>

                    <h3 className="fw-bold mb-0">
                      {
                        inventory.filter(
                          (item) =>
                            Number(item.stock) <= 20
                        ).length
                      }
                    </h3>

                  </div>

                  <div
                    className="bg-warning text-dark rounded-circle d-flex align-items-center justify-content-center"
                    style={{
                      width: "55px",
                      height: "55px",
                      fontSize: "24px",
                    }}
                  >
                    ⚠️
                  </div>

                </div>

              </div>

            </div>

          </div>

        </div>


        {/* Inventory Table */}
        <div className="card border-0 shadow-sm">

          <div className="card-body">

            <div className="d-flex justify-content-between align-items-center mb-3">

              <h5 className="fw-bold mb-0">
                Inventory List
              </h5>

              <span className="badge bg-primary fs-6">
                {inventory.length} Items
              </span>

            </div>


            {/* Loading */}
            {loading ? (

              <div className="text-center py-5">

                <div
                  className="spinner-border text-primary"
                  role="status"
                ></div>

                <p className="text-muted mt-3">
                  Loading inventory...
                </p>

              </div>

            ) : inventory.length === 0 ? (

              /* Empty State */
              <div className="text-center py-5">

                <div className="display-4 mb-3">
                  📦
                </div>

                <h5 className="fw-bold">
                  No Inventory Found
                </h5>

                <p className="text-muted">
                  Add inventory for your products.
                </p>

                <button
                  className="btn btn-primary"
                  onClick={() =>
                    navigate("/add-inventory")
                  }
                >
                  + Add Inventory
                </button>

              </div>

            ) : (

              <div className="table-responsive">

                <table className="table table-hover align-middle mb-0">

                  <thead className="table-dark">

                    <tr>

                      <th>ID</th>

                      <th>Product ID</th>

                      <th>Stock Quantity</th>

                      <th>Status</th>

                      <th className="text-center">
                        Action
                      </th>

                    </tr>

                  </thead>


                  <tbody>

                    {inventory.map((item) => (

                      <tr key={item.id}>

                        {/* ID */}
                        <td>

                          <span className="badge bg-secondary">
                            #{item.id}
                          </span>

                        </td>


                        {/* Product ID */}
                        <td>

                          <span className="badge bg-info text-dark">
                            Product #{item.product_id}
                          </span>

                        </td>


                        {/* Stock */}
                        <td>

                          <strong>
                            {item.stock}
                          </strong>

                          <span className="text-muted ms-1">
                            units
                          </span>

                        </td>


                        {/* Status */}
                        <td>

                          {Number(item.stock) === 0 ? (

                            <span className="badge bg-danger">
                              Out of Stock
                            </span>

                          ) : Number(item.stock) <= 20 ? (

                            <span className="badge bg-warning text-dark">
                              Low Stock
                            </span>

                          ) : (

                            <span className="badge bg-success">
                              In Stock
                            </span>

                          )}

                        </td>


                        {/* Actions */}
                        <td className="text-center">

                          <button
                            className="btn btn-outline-success btn-sm me-2"
                            onClick={() =>
                              navigate(
                                `/editinventory/${item.id}`
                              )
                            }
                          >
                            ✏️ Edit
                          </button>

                          <button
                            className="btn btn-outline-danger btn-sm"
                            onClick={() =>
                              deleteInventory(item.id)
                            }
                          >
                            🗑️ Delete
                          </button>

                        </td>

                      </tr>

                    ))}

                  </tbody>

                </table>

              </div>

            )}

          </div>

        </div>

      </div>

    </div>
  );
}
